-- Schema of the single-company version, as Hibernate generated it.
-- Existing databases already have these tables: Flyway records this version as the baseline and skips it.

create table app_users (id bigint generated by default as identity, role varchar(10) not null check ((role in ('ADMIN','STAFF'))), username varchar(50) not null unique, password varchar(255) not null, primary key (id));
create table categories (id bigint generated by default as identity, name varchar(100) not null unique, description varchar(255), primary key (id));
create table company_settings (id bigint not null, gstin varchar(15), logo_type varchar(20), phone varchar(20), state varchar(50), email varchar(100), name varchar(150) not null, address varchar(255), logo bytea, primary key (id));
create table customers (balance numeric(14,2) not null, id bigint generated by default as identity, gstin varchar(15), phone varchar(20), state varchar(50), email varchar(100), name varchar(150) not null, address varchar(255), primary key (id));
create table payments (amount numeric(14,2) not null, date date not null, customer_id bigint, id bigint generated by default as identity, supplier_id bigint, type varchar(30) not null check ((type in ('SUPPLIER_PAYMENT','CUSTOMER_RECEIPT'))), created_by varchar(255), mode varchar(255), note varchar(255), primary key (id));
create table products (cost_price numeric(14,2) not null, expiry_date date, gst_rate numeric(5,2) default 0 not null, quantity integer not null check ((quantity>=0)), reorder_level integer not null check ((reorder_level>=0)), selling_price numeric(14,2) not null, category_id bigint, hsn_code varchar(8), id bigint generated by default as identity, supplier_id bigint, uom_id bigint, code varchar(50) not null unique, name varchar(150) not null, primary key (id));
create table purchase_items (gst_rate numeric(5,2) default 0 not null, price numeric(14,2) not null, quantity integer not null, tax_amount numeric(14,2) default 0 not null, hsn_code varchar(8), id bigint generated by default as identity, product_id bigint not null, purchase_id bigint not null, primary key (id));
create table purchases (cgst_amount numeric(14,2) default 0 not null, date date not null, due numeric(14,2) not null, igst_amount numeric(14,2) default 0 not null, inter_state boolean default false not null, paid numeric(14,2) not null, sgst_amount numeric(14,2) default 0 not null, subtotal numeric(14,2) not null, taxable_amount numeric(14,2) default 0 not null, id bigint generated by default as identity, supplier_id bigint not null, bill_number varchar(20) unique, created_by varchar(255), description varchar(255), mode varchar(255), primary key (id));
create table sale_items (gst_rate numeric(5,2) default 0 not null, price numeric(14,2) not null, quantity integer not null, tax_amount numeric(14,2) default 0 not null, hsn_code varchar(8), id bigint generated by default as identity, product_id bigint not null, sale_id bigint not null, primary key (id));
create table sales (cgst_amount numeric(14,2) default 0 not null, date date not null, due numeric(14,2) not null, igst_amount numeric(14,2) default 0 not null, inter_state boolean default false not null, paid numeric(14,2) not null, sgst_amount numeric(14,2) default 0 not null, subtotal numeric(14,2) not null, taxable_amount numeric(14,2) default 0 not null, customer_id bigint not null, id bigint generated by default as identity, bill_number varchar(20) unique, created_by varchar(255), description varchar(255), mode varchar(255), primary key (id));
create table suppliers (balance numeric(14,2) not null, id bigint generated by default as identity, gstin varchar(15), phone varchar(20), state varchar(50), email varchar(100), name varchar(150) not null, address varchar(255), primary key (id));
create table uoms (id bigint generated by default as identity, name varchar(50) not null unique, description varchar(255), primary key (id));
alter table if exists payments add constraint FK45dp0030s8e3myd8n6ky4e79g foreign key (customer_id) references customers;
alter table if exists payments add constraint FKr0gunbga56b1mihryahwwqry9 foreign key (supplier_id) references suppliers;
