alter table if exists products add constraint FK6i174ixi9087gcvvut45em7fd foreign key (supplier_id) references suppliers;
alter table if exists products add constraint FKnhm6jltve1mixdx6f8g9eg9ru foreign key (uom_id) references uoms;
