alter table if exists purchase_items add constraint FKhcski0jcuja0o3vhb7o15yqvi foreign key (purchase_id) references purchases;
alter table if exists purchases add constraint FK9ho3w23v5du4x0hrp6rqs1wmh foreign key (supplier_id) references suppliers;
